"""Lexer and recursive-descent parser for minisql ``SELECT`` queries.

``parse(sql)`` returns a ``nodes.Query``; any syntax error raises
``QueryError``. Every expression node's ``text`` is the exact slice of the
source covering that expression (including surrounding parentheses for a
parenthesized expression).
"""

from dataclasses import replace
from typing import List, NamedTuple, Optional

from . import nodes
from .errors import QueryError

__all__ = ["parse"]

KEYWORDS = frozenset("""
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
""".split())

# Token kinds
KEYWORD = "keyword"
NAME = "name"        # identifier (quoted or not); value is the unquoted name
INTEGER = "integer"
DECIMAL = "decimal"
STRING = "string"
OP = "op"
EOF = "end of query"

_OPERATORS = ("<=", ">=", "<>", "!=", "||", "=", "<", ">",
              "+", "-", "*", "/", "(", ")", ",", ";")

_COMPARISONS = ("=", "!=", "<>", "<", "<=", ">", ">=")


class Token(NamedTuple):
    kind: str
    value: object      # keyword (upper-case), name, number, string, or op
    start: int
    end: int
    quoted: bool = False  # for NAME: written in double quotes


def _is_ident_start(c):
    return c.isascii() and (c.isalpha() or c == "_")


def _is_ident_char(c):
    return c.isascii() and (c.isalnum() or c == "_")


def _describe_pos(sql, pos):
    return f"at position {pos + 1}"


def tokenize(sql: str) -> List[Token]:
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        start = i
        if _is_ident_start(c):
            while i < n and _is_ident_char(sql[i]):
                i += 1
            word = sql[start:i]
            if word.upper() in KEYWORDS:
                tokens.append(Token(KEYWORD, word.upper(), start, i))
            else:
                tokens.append(Token(NAME, word, start, i))
            continue
        if c.isdigit() or (c == "." and i + 1 < n and sql[i + 1].isdigit()):
            while i < n and sql[i].isdigit():
                i += 1
            is_decimal = False
            if i < n and sql[i] == ".":
                is_decimal = True
                i += 1
                while i < n and sql[i].isdigit():
                    i += 1
            if i < n and (_is_ident_char(sql[i]) or sql[i] == "."):
                j = i
                while j < n and (_is_ident_char(sql[j]) or sql[j] == "."):
                    j += 1
                raise QueryError(
                    f"invalid number {sql[start:j]!r} "
                    f"{_describe_pos(sql, start)}")
            text = sql[start:i]
            if is_decimal:
                tokens.append(Token(DECIMAL, float(text), start, i))
            else:
                tokens.append(Token(INTEGER, int(text), start, i))
            continue
        if c == "'" or c == '"':
            quote = c
            i += 1
            parts = []
            while True:
                if i >= n:
                    what = "string" if quote == "'" else "quoted name"
                    raise QueryError(
                        f"unterminated {what} starting "
                        f"{_describe_pos(sql, start)}")
                if sql[i] == quote:
                    if i + 1 < n and sql[i + 1] == quote:
                        parts.append(quote)
                        i += 2
                        continue
                    i += 1
                    break
                parts.append(sql[i])
                i += 1
            value = "".join(parts)
            if quote == "'":
                tokens.append(Token(STRING, value, start, i))
            else:
                if value == "":
                    raise QueryError(
                        f"empty quoted name {_describe_pos(sql, start)}")
                tokens.append(Token(NAME, value, start, i, quoted=True))
            continue
        for op in _OPERATORS:
            if sql.startswith(op, i):
                i += len(op)
                tokens.append(Token(OP, op, start, i))
                break
        else:
            raise QueryError(
                f"unexpected character {c!r} {_describe_pos(sql, start)}")
    tokens.append(Token(EOF, None, n, n))
    return tokens


def _token_desc(tok: Token) -> str:
    if tok.kind == EOF:
        return "end of query"
    if tok.kind == KEYWORD:
        return f"keyword {tok.value}"
    if tok.kind == OP:
        return f"{tok.value!r}"
    return f"{tok.kind} {tok.value!r}" if tok.kind != NAME else f"name {tok.value!r}"


class _Parser:
    def __init__(self, sql: str):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers -----------------------------------------------------

    @property
    def tok(self) -> Token:
        return self.tokens[self.pos]

    def peek(self, offset=1) -> Token:
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if tok.kind != EOF:
            self.pos += 1
        return tok

    def at_keyword(self, *words) -> bool:
        return self.tok.kind == KEYWORD and self.tok.value in words

    def at_op(self, *ops) -> bool:
        return self.tok.kind == OP and self.tok.value in ops

    def accept_keyword(self, word) -> Optional[Token]:
        if self.at_keyword(word):
            return self.advance()
        return None

    def accept_op(self, op) -> Optional[Token]:
        if self.at_op(op):
            return self.advance()
        return None

    def error(self, expected: str) -> QueryError:
        tok = self.tok
        return QueryError(
            f"syntax error: expected {expected}, got {_token_desc(tok)} "
            f"{_describe_pos(self.sql, tok.start)}")

    def expect_keyword(self, word) -> Token:
        if not self.at_keyword(word):
            raise self.error(word)
        return self.advance()

    def expect_op(self, op) -> Token:
        if not self.at_op(op):
            raise self.error(repr(op))
        return self.advance()

    def expect_name(self, what="a name") -> str:
        tok = self.tok
        if tok.kind != NAME:
            if tok.kind == KEYWORD:
                raise QueryError(
                    f"syntax error: expected {what}, got keyword {tok.value} "
                    f"{_describe_pos(self.sql, tok.start)} (keywords must be "
                    f"double-quoted to be used as names)")
            raise self.error(what)
        self.advance()
        return tok.value

    def text(self, start: int) -> str:
        """Source text from ``start`` to the end of the last consumed token."""
        end = self.tokens[self.pos - 1].end
        return self.sql[start:end]

    # -- query ---------------------------------------------------------------

    def parse_query(self) -> nodes.Query:
        if self.tok.kind == EOF:
            raise QueryError("empty query")
        self.expect_keyword("SELECT")
        distinct = self.accept_keyword("DISTINCT") is not None

        if self.accept_op("*"):
            columns = None
        else:
            items = [self.parse_select_item()]
            while self.accept_op(","):
                items.append(self.parse_select_item())
            columns = tuple(items)

        if not self.at_keyword("FROM"):
            raise self.error("FROM" if columns is None else "',' or FROM")
        self.advance()
        table = self.expect_name("a table name")

        where = None
        if self.accept_keyword("WHERE"):
            where = self.parse_expr()

        group_by = ()
        if self.accept_keyword("GROUP"):
            self.expect_keyword("BY")
            exprs = [self.parse_expr()]
            while self.accept_op(","):
                exprs.append(self.parse_expr())
            group_by = tuple(exprs)

        having = None
        if self.accept_keyword("HAVING"):
            having = self.parse_expr()

        order_by = ()
        if self.accept_keyword("ORDER"):
            self.expect_keyword("BY")
            items = [self.parse_order_item()]
            while self.accept_op(","):
                items.append(self.parse_order_item())
            order_by = tuple(items)

        limit = offset = None
        if self.accept_keyword("LIMIT"):
            limit = self.parse_count("LIMIT")
            if self.accept_keyword("OFFSET"):
                offset = self.parse_count("OFFSET")

        self.accept_op(";")
        if self.tok.kind != EOF:
            raise self.error("end of query")

        return nodes.Query(
            table=table, columns=columns, distinct=distinct, where=where,
            group_by=group_by, having=having, order_by=order_by,
            limit=limit, offset=offset)

    def parse_select_item(self) -> nodes.SelectItem:
        if self.at_op("*"):
            raise QueryError(
                f"syntax error: '*' must be the only column "
                f"{_describe_pos(self.sql, self.tok.start)}")
        expr = self.parse_expr()
        alias = None
        if self.accept_keyword("AS"):
            alias = self.expect_name("an alias after AS")
        elif self.tok.kind == NAME:
            alias = self.advance().value
        return nodes.SelectItem(expr, alias)

    def parse_order_item(self) -> nodes.OrderItem:
        expr = self.parse_expr()
        descending = False
        if self.accept_keyword("DESC"):
            descending = True
        else:
            self.accept_keyword("ASC")
        return nodes.OrderItem(expr, descending)

    def parse_count(self, clause) -> int:
        tok = self.tok
        if tok.kind != INTEGER:
            raise self.error(f"a non-negative integer after {clause}")
        self.advance()
        return tok.value

    # -- expressions -----------------------------------------------------------

    def parse_expr(self) -> nodes.Expr:
        return self.parse_or()

    def parse_or(self) -> nodes.Expr:
        start = self.tok.start
        left = self.parse_and()
        while self.accept_keyword("OR"):
            right = self.parse_and()
            left = nodes.Binary("OR", left, right, text=self.text(start))
        return left

    def parse_and(self) -> nodes.Expr:
        start = self.tok.start
        left = self.parse_not()
        while self.accept_keyword("AND"):
            right = self.parse_not()
            left = nodes.Binary("AND", left, right, text=self.text(start))
        return left

    def parse_not(self) -> nodes.Expr:
        start = self.tok.start
        if self.accept_keyword("NOT"):
            operand = self.parse_not()
            return nodes.Unary("NOT", operand, text=self.text(start))
        return self.parse_comparison()

    def parse_comparison(self) -> nodes.Expr:
        start = self.tok.start
        left = self.parse_additive()
        result = self._comparison_suffix(left, start)
        if result is left:
            return left
        if self.at_op(*_COMPARISONS) or self.at_keyword(
                "IS", "IN", "BETWEEN", "LIKE") or (
                self.at_keyword("NOT") and self.peek().kind == KEYWORD
                and self.peek().value in ("IN", "BETWEEN", "LIKE")):
            raise QueryError(
                f"syntax error: comparisons can't be chained; use "
                f"parentheses or AND "
                f"{_describe_pos(self.sql, self.tok.start)}")
        return result

    def _comparison_suffix(self, left, start) -> nodes.Expr:
        if self.at_op(*_COMPARISONS):
            op = self.advance().value
            if op == "<>":
                op = "!="
            right = self.parse_additive()
            return nodes.Binary(op, left, right, text=self.text(start))

        if self.accept_keyword("IS"):
            negated = self.accept_keyword("NOT") is not None
            if not self.accept_keyword("NULL"):
                raise self.error("NULL" if negated else "NULL or NOT NULL")
            return nodes.IsNull(left, negated, text=self.text(start))

        negated = False
        if self.at_keyword("NOT"):
            nxt = self.peek()
            if nxt.kind == KEYWORD and nxt.value in ("IN", "BETWEEN", "LIKE"):
                self.advance()
                negated = True
            else:
                self.advance()
                raise self.error("IN, BETWEEN, or LIKE after NOT")

        if self.accept_keyword("IN"):
            self.expect_op("(")
            if self.at_op(")"):
                raise self.error("an expression (IN list can't be empty)")
            items = [self.parse_expr()]
            while self.accept_op(","):
                items.append(self.parse_expr())
            self.expect_op(")")
            return nodes.In(left, tuple(items), negated, text=self.text(start))

        if self.accept_keyword("BETWEEN"):
            low = self.parse_additive()
            self.expect_keyword("AND")
            high = self.parse_additive()
            return nodes.Between(left, low, high, negated,
                                 text=self.text(start))

        if self.accept_keyword("LIKE"):
            pattern = self.parse_additive()
            return nodes.Like(left, pattern, negated, text=self.text(start))

        return left

    def parse_additive(self) -> nodes.Expr:
        start = self.tok.start
        left = self.parse_multiplicative()
        while self.at_op("+", "-", "||"):
            op = self.advance().value
            right = self.parse_multiplicative()
            left = nodes.Binary(op, left, right, text=self.text(start))
        return left

    def parse_multiplicative(self) -> nodes.Expr:
        start = self.tok.start
        left = self.parse_unary()
        while self.at_op("*", "/"):
            op = self.advance().value
            right = self.parse_unary()
            left = nodes.Binary(op, left, right, text=self.text(start))
        return left

    def parse_unary(self) -> nodes.Expr:
        start = self.tok.start
        if self.accept_op("-"):
            operand = self.parse_unary()
            return nodes.Unary("-", operand, text=self.text(start))
        return self.parse_primary()

    def parse_primary(self) -> nodes.Expr:
        tok = self.tok
        start = tok.start
        if tok.kind in (INTEGER, DECIMAL, STRING):
            self.advance()
            return nodes.Literal(tok.value, text=self.text(start))
        if tok.kind == KEYWORD and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            value = {"NULL": None, "TRUE": True, "FALSE": False}[tok.value]
            return nodes.Literal(value, text=self.text(start))
        if tok.kind == NAME:
            self.advance()
            if not tok.quoted and self.at_op("("):
                return self.parse_call(tok.value.upper(), start)
            return nodes.Column(tok.value, text=self.text(start))
        if self.accept_op("("):
            inner = self.parse_expr()
            self.expect_op(")")
            return replace(inner, text=self.text(start))
        if tok.kind == KEYWORD:
            raise QueryError(
                f"syntax error: expected an expression, got keyword "
                f"{tok.value} {_describe_pos(self.sql, tok.start)} (keywords "
                f"must be double-quoted to be used as names)")
        raise self.error("an expression")

    def parse_call(self, name, start) -> nodes.Call:
        self.expect_op("(")
        if self.at_op("*"):
            star_tok = self.advance()
            if name != "COUNT":
                raise QueryError(
                    f"syntax error: '*' is only allowed in COUNT(*), not "
                    f"{name} {_describe_pos(self.sql, star_tok.start)}")
            self.expect_op(")")
            return nodes.Call(name, (), star=True, text=self.text(start))
        args = []
        if not self.at_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        self.expect_op(")")
        return nodes.Call(name, tuple(args), text=self.text(start))


def parse(sql: str) -> nodes.Query:
    """Parse a minisql ``SELECT`` statement into a ``nodes.Query``."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    return _Parser(sql).parse_query()

"""Query execution: run a parsed ``nodes.Query`` against a directory of CSVs.

See SPEC.md, sections "Tables" and "Semantics". Pipeline:
read -> WHERE -> group -> HAVING -> project -> DISTINCT -> ORDER BY -> OFFSET/LIMIT.
"""

import csv
import os
import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

from . import nodes
from .errors import QueryError, Result

__all__ = ["execute"]

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")

AGGREGATES = frozenset(["COUNT", "SUM", "AVG", "MIN", "MAX"])
# name -> (min args, max args or None for unlimited)
SCALARS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

_COMPARISONS = frozenset(["=", "!=", "<", "<=", ">", ">="])
_ARITHMETIC = frozenset(["+", "-", "*", "/"])


# ---------------------------------------------------------------- reading

def _convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


def _read_table(name, directory):
    if not name or "/" in name or "\\" in name or name in (".", ".."):
        raise QueryError(f"invalid table name: {name!r}")
    path = os.path.join(directory, name + ".csv")
    if not os.path.isfile(path):
        raise QueryError(f"no such table: {name}")
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                raise QueryError(f"table {name} has no header line")
            width = len(header)
            rows = []
            for line_no, fields in enumerate(reader, start=2):
                if not fields:
                    continue  # blank line
                if len(fields) > width:
                    raise QueryError(
                        f"{name}.csv line {line_no}: {len(fields)} fields, "
                        f"header has {width}")
                values = [_convert(x) for x in fields]
                values.extend([None] * (width - len(values)))
                rows.append(tuple(values))
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError(f"cannot read table {name}: {e}") from None
    return header, rows


# ---------------------------------------------------------------- values

def _category(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, (int, float)):
        return "number"
    if isinstance(v, str):
        return "text"
    raise QueryError(f"unsupported value: {v!r}")  # pragma: no cover


def _value_key(v):
    """Hashable key for value equality (GROUP BY, DISTINCT): booleans never
    equal numbers; 1 and 1.0 are equal."""
    if v is None:
        return (0,)
    if isinstance(v, bool):
        return (1, v)
    if isinstance(v, (int, float)):
        return (2, v)
    return (3, v)


def _compare(a, b):
    """Three-way compare two non-NULL values per the spec's rules."""
    ca, cb = _category(a), _category(b)
    if ca != cb:
        raise QueryError(f"cannot compare {ca} with {cb}")
    return (a > b) - (a < b)


def _check_bool(v, what):
    if v is not None and not isinstance(v, bool):
        raise QueryError(f"{what} needs a boolean, got {_category(v)}")


def _check_number(v, what):
    if v is not None and _category(v) != "number":
        raise QueryError(f"{what} needs a number, got {_category(v)}")


def _check_text(v, what):
    if v is not None and not isinstance(v, str):
        raise QueryError(f"{what} needs a string, got {_category(v)}")


def _and3(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or3(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _not3(v):
    return None if v is None else not v


def _to_text(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    return str(v)


def _round(x, n=None):
    if isinstance(x, float) and (x != x or x in (float("inf"), float("-inf"))):
        raise QueryError(f"cannot round {x}")
    if n is None:
        if isinstance(x, int):
            return x
        if x.is_integer():
            return int(x)
        d = Decimal(repr(x))
        return int(d.quantize(Decimal(1), rounding=ROUND_HALF_UP))
    d = Decimal(x) if isinstance(x, int) else Decimal(repr(x))
    try:
        with localcontext() as ctx:
            ctx.prec = 2000
            q = d.quantize(Decimal(1).scaleb(-n), rounding=ROUND_HALF_UP)
        return float(q) + 0.0  # + 0.0 turns -0.0 into 0.0
    except InvalidOperation:
        return float(x)


_like_cache = {}


def _like(s, pattern):
    rx = _like_cache.get(pattern)
    if rx is None:
        parts = []
        for ch in pattern:
            if ch == "%":
                parts.append(".*")
            elif ch == "_":
                parts.append(".")
            else:
                parts.append(re.escape(ch))
        rx = re.compile("".join(parts), re.DOTALL)
        _like_cache[pattern] = rx
    return rx.fullmatch(s) is not None


# ---------------------------------------------------------------- AST helpers

def _children(e):
    if isinstance(e, (nodes.Literal, nodes.Column)):
        return ()
    if isinstance(e, nodes.Unary):
        return (e.operand,)
    if isinstance(e, nodes.Binary):
        return (e.left, e.right)
    if isinstance(e, nodes.IsNull):
        return (e.operand,)
    if isinstance(e, nodes.In):
        return (e.operand,) + tuple(e.items)
    if isinstance(e, nodes.Between):
        return (e.operand, e.low, e.high)
    if isinstance(e, nodes.Like):
        return (e.operand, e.pattern)
    if isinstance(e, nodes.Call):
        return tuple(e.args)
    raise QueryError(f"unknown expression node: {type(e).__name__}")


def _norm(e):
    """Structural key: column names lower-cased, literal types distinguished."""
    if isinstance(e, nodes.Literal):
        return ("lit", type(e.value).__name__, e.value)
    if isinstance(e, nodes.Column):
        return ("col", e.name.lower())
    if isinstance(e, nodes.Unary):
        return ("unary", e.op, _norm(e.operand))
    if isinstance(e, nodes.Binary):
        return ("binary", e.op, _norm(e.left), _norm(e.right))
    if isinstance(e, nodes.IsNull):
        return ("isnull", e.negated, _norm(e.operand))
    if isinstance(e, nodes.In):
        return ("in", e.negated, _norm(e.operand),
                tuple(_norm(i) for i in e.items))
    if isinstance(e, nodes.Between):
        return ("between", e.negated, _norm(e.operand), _norm(e.low),
                _norm(e.high))
    if isinstance(e, nodes.Like):
        return ("like", e.negated, _norm(e.operand), _norm(e.pattern))
    if isinstance(e, nodes.Call):
        return ("call", e.name.upper(), e.star,
                tuple(_norm(a) for a in e.args))
    raise QueryError(f"unknown expression node: {type(e).__name__}")


def _is_aggregate(e):
    return isinstance(e, nodes.Call) and e.name.upper() in AGGREGATES


def _contains_aggregate(e):
    return _is_aggregate(e) or any(_contains_aggregate(c) for c in _children(e))


# ---------------------------------------------------------------- engine

class _Engine:
    def __init__(self, header):
        self.header = header
        self.colmap = {}
        for i, name in enumerate(header):
            self.colmap.setdefault(name.lower(), i)

    # -- static checks

    def validate(self, e, where_ok_agg, clause, in_agg=False):
        """Check column names, functions, arity and aggregate placement."""
        if isinstance(e, nodes.Column):
            if e.name.lower() not in self.colmap:
                raise QueryError(f"unknown column: {e.name}")
            return
        if isinstance(e, nodes.Call):
            name = e.name.upper()
            if name in AGGREGATES:
                if not where_ok_agg:
                    raise QueryError(f"aggregate {name} not allowed in {clause}")
                if in_agg:
                    raise QueryError("aggregates cannot be nested")
                if e.star:
                    if name != "COUNT" or e.args:
                        raise QueryError(f"{name}(*) is not allowed")
                elif len(e.args) != 1:
                    raise QueryError(
                        f"{name} takes 1 argument, got {len(e.args)}")
                for a in e.args:
                    self.validate(a, where_ok_agg, clause, True)
                return
            if name in SCALARS:
                lo, hi = SCALARS[name]
                if e.star:
                    raise QueryError(f"{name}(*) is not allowed")
                n = len(e.args)
                if n < lo or (hi is not None and n > hi):
                    if lo == hi:
                        want = str(lo)
                    elif hi is None:
                        want = f"at least {lo}"
                    else:
                        want = f"{lo} to {hi}"
                    raise QueryError(
                        f"{name} takes {want} argument(s), got {n}")
                for a in e.args:
                    self.validate(a, where_ok_agg, clause, in_agg)
                return
            raise QueryError(f"unknown function: {e.name}")
        for c in _children(e):
            self.validate(c, where_ok_agg, clause, in_agg)

    def check_grouped(self, e, groupset):
        if _norm(e) in groupset or _is_aggregate(e):
            return
        if isinstance(e, nodes.Column):
            raise QueryError(
                f"column {e.name} must be in GROUP BY or inside an aggregate")
        for c in _children(e):
            self.check_grouped(c, groupset)

    # -- evaluation. ``row`` is a tuple (first row of the group in grouped
    # queries, None for an empty group); ``group`` is a list of rows or None.

    def ev(self, e, row, group):
        if isinstance(e, nodes.Literal):
            return e.value
        if isinstance(e, nodes.Column):
            return row[self.colmap[e.name.lower()]]
        if isinstance(e, nodes.Unary):
            v = self.ev(e.operand, row, group)
            if e.op == "-":
                _check_number(v, "unary -")
                return None if v is None else -v
            if e.op.upper() == "NOT":
                _check_bool(v, "NOT")
                return _not3(v)
            raise QueryError(f"unknown operator: {e.op}")
        if isinstance(e, nodes.Binary):
            return self.binary(e.op, self.ev(e.left, row, group),
                               self.ev(e.right, row, group))
        if isinstance(e, nodes.IsNull):
            v = self.ev(e.operand, row, group)
            return (v is None) != e.negated
        if isinstance(e, nodes.In):
            v = self.ev(e.operand, row, group)
            found = False
            saw_null = v is None
            for item in e.items:
                iv = self.ev(item, row, group)
                if iv is None:
                    saw_null = True
                elif v is not None and _compare(v, iv) == 0:
                    found = True
            r = True if found else (None if saw_null else False)
            return _not3(r) if e.negated else r
        if isinstance(e, nodes.Between):
            v = self.ev(e.operand, row, group)
            lo = self.ev(e.low, row, group)
            hi = self.ev(e.high, row, group)
            r = _and3(self.binary("<=", lo, v), self.binary("<=", v, hi))
            return _not3(r) if e.negated else r
        if isinstance(e, nodes.Like):
            s = self.ev(e.operand, row, group)
            p = self.ev(e.pattern, row, group)
            _check_text(s, "LIKE")
            _check_text(p, "LIKE")
            if s is None or p is None:
                return None
            r = _like(s, p)
            return (not r) if e.negated else r
        if isinstance(e, nodes.Call):
            name = e.name.upper()
            if name in AGGREGATES:
                return self.aggregate(name, e, group)
            return self.scalar(name, [self.ev(a, row, group) for a in e.args])
        raise QueryError(f"unknown expression node: {type(e).__name__}")

    def binary(self, op, a, b):
        if op in ("AND", "OR"):
            _check_bool(a, op)
            _check_bool(b, op)
            return _and3(a, b) if op == "AND" else _or3(a, b)
        if op in _COMPARISONS:
            if a is None or b is None:
                return None
            c = _compare(a, b)
            return {"=": c == 0, "!=": c != 0, "<": c < 0, "<=": c <= 0,
                    ">": c > 0, ">=": c >= 0}[op]
        if op in _ARITHMETIC:
            _check_number(a, op)
            _check_number(b, op)
            if a is None or b is None:
                return None
            try:
                if op == "+":
                    r = a + b
                elif op == "-":
                    r = a - b
                elif op == "*":
                    r = a * b
                else:
                    if b == 0:
                        return None
                    return float(a / b)
            except OverflowError:
                raise QueryError(f"numeric overflow in {op}") from None
            if isinstance(r, int) and not (isinstance(a, int) and isinstance(b, int)):
                r = float(r)  # pragma: no cover - int op float is always float
            return r
        if op == "||":
            if a is None or b is None:
                return None
            return _to_text(a) + _to_text(b)
        raise QueryError(f"unknown operator: {op}")

    def scalar(self, name, args):
        if name == "COALESCE":
            for v in args:
                if v is not None:
                    return v
            return None
        if name in ("LOWER", "UPPER", "LENGTH"):
            (s,) = args
            _check_text(s, name)
            if s is None:
                return None
            return s.lower() if name == "LOWER" else (
                s.upper() if name == "UPPER" else len(s))
        if name == "ABS":
            (x,) = args
            _check_number(x, name)
            return None if x is None else abs(x)
        if name == "ROUND":
            x = args[0]
            _check_number(x, name)
            if len(args) == 2:
                n = args[1]
                if n is not None and (isinstance(n, bool) or not isinstance(n, int)):
                    raise QueryError("ROUND places must be an integer")
                if x is None or n is None:
                    return None
                try:
                    return _round(x, n)
                except OverflowError:
                    raise QueryError("numeric overflow in ROUND") from None
            return None if x is None else _round(x)
        raise QueryError(f"unknown function: {name}")  # pragma: no cover

    def aggregate(self, name, e, group):
        rows = group or []
        if e.star:
            return len(rows)
        arg = e.args[0]
        values = [self.ev(arg, r, None) for r in rows]
        values = [v for v in values if v is not None]
        if name == "COUNT":
            return len(values)
        if name in ("SUM", "AVG"):
            for v in values:
                _check_number(v, name)
            if not values:
                return None
            try:
                if all(isinstance(v, int) for v in values):
                    total = sum(values)
                    return total if name == "SUM" else float(total / len(values))
                total = float(sum(values))
                return total if name == "SUM" else total / len(values)
            except OverflowError:
                raise QueryError(f"numeric overflow in {name}") from None
        # MIN / MAX
        if not values:
            return None
        best = values[0]
        for v in values[1:]:
            c = _compare(v, best)
            if (c < 0) if name == "MIN" else (c > 0):
                best = v
        return best


def _condition(v, clause):
    if v is not None and not isinstance(v, bool):
        raise QueryError(f"{clause} condition must be boolean, got {_category(v)}")
    return v is True


def execute(query, directory):
    """Run ``query`` (a ``nodes.Query``) against CSVs in ``directory``."""
    for label, n in (("LIMIT", query.limit), ("OFFSET", query.offset)):
        if n is not None and (isinstance(n, bool) or not isinstance(n, int) or n < 0):
            raise QueryError(f"{label} must be a non-negative integer")

    header, rows = _read_table(query.table, directory)
    eng = _Engine(header)

    # Output columns: (name, expr) where expr is None for a '*' column index.
    if query.columns is None:
        out_names = list(header)
        out_exprs = [nodes.Column(h, text=h) for h in header]
    else:
        out_names, out_exprs = [], []
        for item in query.columns:
            eng.validate(item.expr, True, "SELECT")
            if item.alias is not None:
                out_names.append(item.alias)
            elif isinstance(item.expr, nodes.Column):
                out_names.append(header[eng.colmap[item.expr.name.lower()]])
            else:
                out_names.append(item.expr.text)
            out_exprs.append(item.expr)

    if query.where is not None:
        eng.validate(query.where, False, "WHERE")
    for g in query.group_by:
        eng.validate(g, False, "GROUP BY")
    if query.having is not None:
        eng.validate(query.having, True, "HAVING")

    # Resolve ORDER BY items: ("out", index) or ("expr", expr).
    lowered_names = [n.lower() for n in out_names]
    order = []
    for item in query.order_by:
        e = item.expr
        if isinstance(e, nodes.Column) and e.name.lower() in lowered_names:
            order.append(("out", lowered_names.index(e.name.lower()), item.descending))
        elif (isinstance(e, nodes.Literal) and isinstance(e.value, int)
              and not isinstance(e.value, bool)):
            if not 1 <= e.value <= len(out_names):
                raise QueryError(f"ORDER BY position {e.value} is out of range")
            order.append(("out", e.value - 1, item.descending))
        else:
            eng.validate(e, True, "ORDER BY")
            order.append(("expr", e, item.descending))

    grouped = bool(query.group_by) or any(
        _contains_aggregate(e) for e in
        ([] if query.columns is None else out_exprs)
        + ([query.having] if query.having is not None else [])
        + [o[1] for o in order if o[0] == "expr"])

    if grouped:
        groupset = {_norm(g) for g in query.group_by}
        if query.columns is None:
            for h in header:
                if ("col", h.lower()) not in groupset:
                    raise QueryError(
                        f"SELECT * in a grouped query: column {h} is not in GROUP BY")
        else:
            for e in out_exprs:
                eng.check_grouped(e, groupset)
        if query.having is not None:
            eng.check_grouped(query.having, groupset)
        for kind, e, _ in order:
            if kind == "expr":
                eng.check_grouped(e, groupset)

    # WHERE
    if query.where is not None:
        rows = [r for r in rows
                if _condition(eng.ev(query.where, r, None), "WHERE")]

    # Grouping: units are (row, group).
    if grouped:
        if query.group_by:
            groups = {}
            for r in rows:
                key = tuple(_value_key(eng.ev(g, r, None)) for g in query.group_by)
                groups.setdefault(key, []).append(r)
            units = [(g[0], g) for g in groups.values()]
        else:
            units = [(rows[0] if rows else None, rows)]
    else:
        units = [(r, None) for r in rows]

    # HAVING (a row filter when the query is not grouped)
    if query.having is not None:
        units = [u for u in units
                 if _condition(eng.ev(query.having, u[0], u[1]), "HAVING")]

    # Project
    results = [(tuple(eng.ev(e, u[0], u[1]) for e in out_exprs), u) for u in units]

    # DISTINCT (keeps first occurrence, and its source row/group for ORDER BY)
    if query.distinct:
        seen = set()
        kept = []
        for out, u in results:
            k = tuple(_value_key(v) for v in out)
            if k not in seen:
                seen.add(k)
                kept.append((out, u))
        results = kept

    # ORDER BY: successive stable sorts from the last key to the first.
    if order:
        keyed = []
        for out, u in results:
            ks = []
            for kind, ref, _ in order:
                ks.append(out[ref] if kind == "out" else eng.ev(ref, u[0], u[1]))
            keyed.append((ks, out))
        for i in range(len(order) - 1, -1, -1):
            cats = {_category(ks[i]) for ks, _ in keyed} - {None}
            if len(cats) > 1:
                raise QueryError(
                    "ORDER BY cannot compare " + " with ".join(sorted(cats)))
            desc = order[i][2]
            # NULL sorts lowest, so it is first ascending and last descending.
            # sort(reverse=True) keeps ties in their original order.
            keyed.sort(key=lambda kv, i=i: (kv[0][i] is not None,
                                            kv[0][i] if kv[0][i] is not None else 0),
                       reverse=desc)
        results = [(out, None) for _, out in keyed]

    out_rows = [out for out, _ in results]
    start = query.offset or 0
    out_rows = out_rows[start:]
    if query.limit is not None:
        out_rows = out_rows[:query.limit]
    return Result(list(out_names), out_rows)

